class Solution { public int minSizeSubarray(int[] nums,int target){int n=nums.length;long total=0;for(int value:nums)total+=value;long quotient=target/total,remainder=target%total;if(remainder==0)return (int)(quotient*n);int left=0,best=Integer.MAX_VALUE;long window=0;for(int right=0;right<2*n;right++){window+=nums[right%n];while(window>remainder&&left<=right)window-=nums[left++%n];if(window==remainder)best=Math.min(best,right-left+1);}return best==Integer.MAX_VALUE?-1:(int)(quotient*n+best);} }
